use bytes::{Buf, BufMut, BytesMut};
use std::io;
use tokio_util::codec::{Decoder, Encoder};

pub struct LengthPrefixedStringCodec;

impl Decoder for LengthPrefixedStringCodec {
    type Item = String;
    type Error = io::Error;

    fn decode(&mut self, src: &mut BytesMut) -> Result<Option<Self::Item>, Self::Error> {
        // 1. نتأكد إن عندنا 4 بايت على الأقل عشان نقرأ الطول:
        if src.len() < 4 {
            return Ok(None); // لسه البيانات مجاتش كاملة من الشبكة
        }

        // 2. قراءة طول الرسالة بدون مسحها من الـ Buffer:
        let mut length_bytes = [0u8; 4];
        length_bytes.copy_from_slice(&src[..4]);
        let msg_len = u32::from_be_bytes(length_bytes) as usize;

        // 3. نتأكد إن الرسالة كاملة وصلت في الـ Buffer:
        if src.len() < 4 + msg_len {
            src.reserve(4 + msg_len - src.len());
            return Ok(None); // في انتظار باقي البايتات
        }

        // 4. استخراج الرسالة وتحويلها لـ String:
        src.advance(4); // تخطي الـ 4 بايت الخاصة بالطول
        let data = src.split_to(msg_len);
        let s = String::from_utf8(data.to_vec())
            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;

        Ok(Some(s))
    }
}

impl Encoder<String> for LengthPrefixedStringCodec {
    type Error = io::Error;

    fn encode(&mut self, item: String, dst: &mut BytesMut) -> Result<(), Self::Error> {
        let len = item.len() as u32;
        dst.reserve(4 + item.len());
        dst.put_u32(len); // كتابة الطول في أول 4 بايت
        dst.put_slice(item.as_bytes()); // كتابة نص الرسالة
        Ok(())
    }
}

use tokio::net::TcpListener;
use tokio_util::codec::Framed;
use futures::{SinkExt, StreamExt};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let listener = TcpListener::bind("127.0.0.1:8080").await?;
    println!("📡 سيرفر الـ Framed TCP شغال على 8080...");

    while let Ok((socket, addr)) = listener.accept().await {
        println!("اتصال جديد من: {}", addr);

        tokio::spawn(async move {
            // تحويل الـ Raw TCP Socket إلى تيار رسائل مهيكل:
            let mut framed = Framed::new(socket, LengthPrefixedStringCodec);

            // القراءة والإرسال أصبحت بمستوى الرسائل الكاملة:
            while let Some(Ok(message)) = framed.next().await {
                println!("استلمت رسالة كاملة: {}", message);

                // الرد برسالة مؤطرة أيضاً:
                let response = format!("Echo: {}", message);
                if let Err(e) = framed.send(response).await {
                    eprintln!("فشل الإرسال: {}", e);
                    break;
                }
            }
        });
    }

    Ok(())
}
